ALTER TABLE public.poker_diamond_tournament_ledger DROP CONSTRAINT poker_diamond_tournament_ledger_kind_check;
ALTER TABLE public.poker_diamond_tournament_ledger ADD CONSTRAINT poker_diamond_tournament_ledger_kind_check CHECK ((kind = ANY (ARRAY['entry'::text, 'rebuy'::text, 'reentry'::text, 'addon'::text, 'prize'::text, 'bounty'::text, 'fee'::text, 'refund'::text, 'spin_underwrite'::text, 'spin_surplus'::text, 'overlay'::text, 'overlay_return'::text])));
ALTER TABLE public.poker_diamond_tournament_ledger DROP CONSTRAINT poker_diamond_tournament_ledger_outflow;
ALTER TABLE public.poker_diamond_tournament_ledger ADD CONSTRAINT poker_diamond_tournament_ledger_outflow CHECK ((((kind = ANY (ARRAY['prize'::text, 'bounty'::text, 'refund'::text])) AND (user_id IS NOT NULL)) OR ((kind = 'fee'::text) AND (user_id IS NULL) AND (prize_part = 0) AND (bounty_part = 0)) OR (kind = ANY (ARRAY['entry'::text, 'rebuy'::text, 'reentry'::text, 'addon'::text])) OR ((kind = ANY (ARRAY['spin_underwrite'::text, 'spin_surplus'::text, 'overlay'::text, 'overlay_return'::text])) AND (user_id IS NOT NULL) AND (custody_id IS NOT NULL) AND (prize_part = amount) AND (bounty_part = 0) AND (fee_part = 0))));
